import pandas as pd
import numpy as np
from scipy.stats import zscore

# Load the data
df = pd.read_csv('chunks_csv/getisord/getisord_2021_no2.csv')
adjacency = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Drop rows with missing NO2 values
df = df.dropna()

# Calculate the citywide average
citywide_avg = df['NO2_value'].mean()

# Create a dictionary to store the neighbors of each borough
neighbors_dict = {}
for index, row in adjacency.iterrows():
    if row['borough'] not in neighbors_dict:
        neighbors_dict[row['borough']] = []
    neighbors_dict[row['borough']].append(row['neighbor'])

# Create a dictionary to store the NO2 values of each borough
no2_dict = {}
for index, row in df.iterrows():
    no2_dict[row['borough']] = row['NO2_value']

# Create a dictionary to store the combined NO2 values of each borough and its neighbors
combined_no2_dict = {}
for borough, neighbors in neighbors_dict.items():
    combined_no2 = no2_dict[borough]
    for neighbor in neighbors:
        if neighbor in no2_dict:
            combined_no2 += no2_dict[neighbor]
    combined_no2_dict[borough] = combined_no2

# Calculate the z-scores of the combined NO2 values
z_scores = zscore(list(combined_no2_dict.values()))

# Identify the hot and cold spots
hot_spots = []
cold_spots = []
for i, borough in enumerate(combined_no2_dict.keys()):
    if z_scores[i] > 1.96:
        hot_spots.append((borough, z_scores[i]))
    elif z_scores[i] < -1.96:
        cold_spots.append((borough, z_scores[i]))

# Print the final answer
if not hot_spots and not cold_spots:
    print("FINAL ANSWER: none")
else:
    final_answer = "FINAL ANSWER: "
    for borough, z_score in hot_spots:
        final_answer += f"{borough} (HOT, z-score = {z_score}), "
    for borough, z_score in cold_spots:
        final_answer += f"{borough} (COLD, z-score = {z_score}), "
    print(final_answer[:-2])  # Remove the trailing comma and space
